{
  "wire_schema": "role_benchmark.player_action",
  "kind": "experiment",
  "portfolio": {
    "hypotheses": [
      {
        "hypothesis_id": "H1",
        "statement": "The photoelectric effect follows Einstein's law: stopping potential is linear in frequency above a threshold, independent of intensity; saturation current is proportional to intensity when above threshold.",
        "confidence": 0.5
      },
      {
        "hypothesis_id": "H2",
        "statement": "The photoelectric effect has a threshold frequency, but the stopping potential also depends on intensity (e.g., due to multi-photon or thermal effects).",
        "confidence": 0.3
      },
      {
        "hypothesis_id": "H3",
        "statement": "There is no clear threshold; electrons are emitted at all frequencies with stopping potential proportional to intensity and frequency.",
        "confidence": 0.2
      }
    ]
  },
  "experiment": {
    "intent": "Probe the threshold frequency and the dependence of stopping potential on frequency and intensity.",
    "apparatus": "vacuum_phototube",
    "controls": {
      "frequency_thz": 600,
      "intensity_relative": 1.0
    },
    "readouts": [
      "stopping_potential_v",
      "saturation_current_ua"
    ],
    "replicates": 3,
    "forecasts": {
      "H1": {
        "stopping_potential_v": 0.5,
        "saturation_current_ua": 1.0
      },
      "H2": {
        "stopping_potential_v": 0.6,
        "saturation_current_ua": 1.0
      },
      "H3": {
        "stopping_potential_v": 0.8,
        "saturation_current_ua": 1.0
      }
    }
  },
  "final": null
}

